const puml = exported.definition;

// hex-encode the PlantUML text (UTF-8)
const bytes = [];
for (let i = 0; i < puml.length; i++) {
  let c = puml.charCodeAt(i);
  if (c < 0x80) bytes.push(c);
  else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
  else bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
}
const hex = bytes.map(b => b.toString(16).padStart(2, "0")).join("");

const url = `https://www.plantuml.com/plantuml/png/hex/${hex}`;
const res = await fetch(url);
if (!res.ok) return { error: `HTTP ${res.status}`, body: (await res.text()).slice(0, 500) };

const png = new Uint8Array(await res.arrayBuffer());
// verify PNG magic
const isPng = png[0] === 0x89 && png[1] === 0x50 && png[2] === 0x4e && png[3] === 0x47;

// base64-encode for transfer
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
